sys_script_include.script:
var TierActivationUtil = Class.create()
TierActivationUtil.prototype = {
    initialize: function () {},

    /**
     * Checks if the Service Portal plugin is active.
     * @returns {boolean} true if com.glide.service-portal is active
     */
    isServicePortalAvailable: function () {
        return this.checkTier('com.glide.service-portal')
    },

    /**
     * Checks if the Integration Hub plugin is active.
     * @returns {boolean} true if com.glide.hub.integrations is active
     */
    isIntegrationHubAvailable: function () {
        return this.checkTier('com.glide.hub.integrations')
    },

    /**
     * Checks if the Flow Designer plugin is active.
     * @returns {boolean} true if com.glide.hub.flow_designer is active
     */
    isFlowDesignerAvailable: function () {
        return this.checkTier('com.glide.hub.flow_designer')
    },

    /**
     * Checks if the Automated Test Framework plugin is active.
     * @returns {boolean} true if com.glide.testing is active
     */
    isATFAvailable: function () {
        return this.checkTier('com.glide.testing')
    },

    /**
     * Generic method that checks if a given plugin is active.
     * Logs a warning if the plugin is not available.
     * @param {string} pluginId - The plugin identifier to check
     * @returns {boolean} true if the plugin is active, false otherwise
     */
    checkTier: function (pluginId) {
        var pm = new GlidePluginManager()
        var isActive = pm.isActive(pluginId)
        if (!isActive) {
            gs.warn(
                'TierActivationUtil: Plugin "' +
                    pluginId +
                    '" is not active on this instance. Features depending on it will be unavailable.'
            )
        }
        return isActive
    },

    type: 'TierActivationUtil',
}
